SINA_SMART["anat2-colon"] = {"lecture":"anat2-colon","title":"The colon and appendix","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-colon:e0","text":"Colon: water absorption, vitamins K and B, faeces storage.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e4","text":"Ascending (right flank) → hepatic flexure → transverse (mesocolon) → splenic flexure → descending → sigmoid.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e1","text":"Unique features: taeniae coli, haustra, omental appendices.","topic":"Features and parts","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e2","text":"Caecum: right iliac fossa (75%), intraperitoneal.","topic":"Features and parts","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e3","text":"Appendix: 6-10 cm; base where taeniae converge; McBurney's point; variable tip.","topic":"Features and parts","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e5","text":"Sigmoid: ~40 cm, mesocolon over left ureter.","topic":"Features and parts","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e6","text":"SMA: ileocolic, right colic, middle colic.","topic":"Vessels and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e7","text":"IMA: left colic, sigmoid, superior rectal.","topic":"Vessels and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e8","text":"Marginal artery links SMA and IMA.","topic":"Vessels and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-colon:e9","text":"Lymph: epicolic → paracolic → intermediate → mesenteric nodes.","topic":"Vessels and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1bkgmww":"a","3b3y9s":"a","1gr0z4i":"a","349dd0":"a","1y6ls46":"a","11gbhlt":"a","4lfbuh":"a","1p5w2b6":"a","1bqet8x":"a","1bkl4ww":"a","ez2id9":"a","dx3jqw":"x"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-colon:e0":{"s":0,"u":["Colon: water absorption, vitamins K and B, faeces storage.","The large intestine absorbs water , produces vitamins K and B (bacterial flora), compacts and stores faeces and moves them toward the rectum.","Parts: caecum (with appendix), ascending colon , hepatic flexure, transverse colon , splenic flexure, descending colon , sigmoid colon , then rectum."],"dp":[]},"anat2-colon:e4":{"s":0,"u":["Ascending (right flank) → hepatic flexure → transverse (mesocolon) → splenic flexure → descending → sigmoid.","Parts: caecum (with appendix), ascending colon , hepatic flexure, transverse colon , splenic flexure, descending colon , sigmoid colon , then rectum."],"dp":[{"h":"Clinical","t":"Watershed areas (splenic flexure, rectosigmoid) sit between two arterial territories: most vulnerable in ischaemic colitis ."},{"h":"Note","t":"Intraperitoneal : caecum (mostly), transverse and sigmoid colon (mobile on a mesocolon). Retroperitoneal : ascending and descending colon."}]},"anat2-colon:e1":{"s":1,"u":["Unique features: taeniae coli, haustra, omental appendices.","Features unique to the colon: taeniae coli (three bands of longitudinal muscle), haustra (sacculations) and omental (epiploic) appendices (fat tags)."],"dp":[{"h":"Note","t":"Colon hallmarks: taeniae coli (3 bands), haustra , epiploic appendices . The small intestine has none of them."}]},"anat2-colon:e2":{"s":1,"u":["Caecum: right iliac fossa (75%), intraperitoneal.","Caecum : usually in the right iliac fossa (75%), sometimes pelvic or subhepatic; intraperitoneal; lies on the iliacus, with the ileum and appendix medially."],"dp":[{"h":"Clinical","t":"Appendicitis pain starts periumbilical (visceral, T10, midgut) then moves to the right iliac fossa when the parietal peritoneum is irritated."}]},"anat2-colon:e3":{"s":1,"u":["Appendix: 6-10 cm; base where taeniae converge; McBurney's point; variable tip.","Appendix : blind diverticulum 6-10 cm long, whose base is on the posteromedial caecum below the ileocaecal junction, where the three taeniae converge (surgical landmark); vessels run in the mesoappendix ; the base projects at McBurney's point , but the tip position varies, so appendicitis pain can be felt in different places."],"dp":[{"h":"Clinical","t":"Appendix base is where the three taeniae converge (surgical landmark). McBurney's point : one third of the way from the ASIS to the umbilicus. The tip position varies (retrocaecal most often), so pain location varies."}]},"anat2-colon:e5":{"s":1,"u":["Sigmoid: ~40 cm, mesocolon over left ureter.","Ascending colon (right flank; about 10 cm, 6 cm wide) to the hepatic flexure; transverse colon , mobile on the transverse mesocolon ; descending colon (left flank; about 25 cm, 4 cm wide), from the splenic flexure, fixed to the posterior wall; sigmoid colon (about 40 cm, 3 cm wide), mobile on the sigmoid mesocolon , whose root lies over the left ureter , related to the pouch of Douglas and, in women, the ovary."],"dp":[{"h":"Note","t":"The sigmoid mesocolon root lies over the left ureter : identify the ureter in sigmoid surgery. Sigmoid mobility → volvulus ."}]},"anat2-colon:e6":{"s":2,"u":["SMA: ileocolic, right colic, middle colic.","Superior mesenteric artery (midgut): ileocolic (caecum, appendix), right colic (ascending colon), middle colic (transverse colon).","Inferior mesenteric artery (hindgut): left colic , sigmoid arteries and superior rectal artery."],"dp":[{"h":"Note","t":"SMA (midgut) : ileocolic, right colic, middle colic. IMA (hindgut) : left colic, sigmoid, superior rectal. The marginal artery links them."}]},"anat2-colon:e7":{"s":2,"u":["IMA: left colic, sigmoid, superior rectal.","Inferior mesenteric artery (hindgut): left colic , sigmoid arteries and superior rectal artery.","Superior mesenteric artery (midgut): ileocolic (caecum, appendix), right colic (ascending colon), middle colic (transverse colon)."],"dp":[]},"anat2-colon:e8":{"s":2,"u":["Marginal artery links SMA and IMA.","The marginal artery links them along the colon.","Inferior mesenteric artery (hindgut): left colic , sigmoid arteries and superior rectal artery."],"dp":[{"h":"Why the splenic flexure is vulnerable to ischaemia","t":"The splenic flexure sits at the boundary between the SMA (midgut) and IMA (hindgut) territories. Only the marginal artery connects them there, and in some people this link is thin. When blood pressure drops or one artery is blocked, this watershed zone is the first to suffer, making ischaemic colitis most common at the splenic flexure. Source: the lecture's arterial supply slides."}]},"anat2-colon:e9":{"s":2,"u":["Lymph: epicolic → paracolic → intermediate → mesenteric nodes.","Lymph passes through a chain of nodes: epicolic (on the wall) → paracolic → intermediate (ileocolic, mesocolic, sigmoid) → main ( superior and inferior mesenteric ) nodes, which is why colon cancer surgery removes the colon with its mesentery and vessels."],"dp":[{"h":"Clinical","t":"Lymph follows the arteries (epicolic → paracolic → intermediate → main), so cancer surgery removes the colon with its mesentery and vascular pedicle ."}]}},"meta":{"1bkgmww":{"a":"recall","vg":"anat2-colon:e1/recall/1"},"3b3y9s":{"a":"recall","vg":"anat2-colon:e2/recall/1"},"1gr0z4i":{"a":"recall","vg":"anat2-colon:e3/recall/1"},"349dd0":{"a":"recall","vg":"anat2-colon:e3/recall/2"},"1y6ls46":{"a":"relationship","vg":"anat2-colon:e3/relationship/1"},"11gbhlt":{"a":"recall","vg":"anat2-colon:e5/recall/1"},"4lfbuh":{"a":"recall","vg":"anat2-colon:e5/recall/2"},"1p5w2b6":{"a":"recall","vg":"anat2-colon:e6/recall/1"},"1bqet8x":{"a":"recall","vg":"anat2-colon:e8/recall/1"},"1bkl4ww":{"a":"recall","vg":"anat2-colon:e7/recall/1"},"ez2id9":{"a":"recall","vg":"anat2-colon:e8/recall/2"}},"explRev":"56337c07d5d1"};
